  add('gitflow-semver','Elegir una versión semántica','Decide MAJOR, MINOR o PATCH por compatibilidad y cambios desde la última versión.','version versiones semver semantico major minor patch breaking change etiqueta tag rc',[
    step('Listar etiquetas de versión','git tag --list --sort=-version:refname','El orden de Git es orientativo; no sustituye a un comparador SemVer para todos los sufijos.'),
    step('Revisar commits desde la última versión','git log --oneline v1.2.3..HEAD','Sustituye v1.2.3 por tu última etiqueta y revisa el impacto público real de los cambios.')
  ],{source:'https://semver.org/lang/es/',note:'Desde 1.2.3: una corrección compatible da 1.2.4; una nueva función compatible da 1.3.0; una incompatibilidad pública da 2.0.0. Escoge el impacto mayor del conjunto. El tipo de rama no decide por sí solo la versión y Git no incrementa versiones automáticamente.',vscode:[ui('Revisar el historial','Consulta los commits y cambios desde la última etiqueta publicada.'),ui('Elegir el impacto','Usa el asistente de Versiones de Convenciones y verifica la compatibilidad de la API o contrato público.'),ui('Usar la versión elegida','Para una release introduce la versión de destino en Release: Start. Revisa la etiqueta vX.Y.Z antes de publicar.') ]});
