/* ===== interfaz de convenciones ===== */
globalThis.SemanticsUI = (() => {
  const S=GitflowSemantics;
  let esc,icon;
  const values={commit:{type:'feat',scope:'auth',customScope:'permisos',description:'agregar recuperación de contraseña',breaking:false,breakingDetail:''},branch:{kind:'feature',scope:'auth',ticket:'123',description:'recuperar contraseña',version:'1.3.0'},version:{current:'1.2.3',change:'minor'},diagram:'feature'};
  const examples=['feat(ui): agregar formulario de registro','feat(auth): implementar inicio de sesión','feat(api): crear endpoint de permisos','feat(db): agregar migración de usuarios','feat(files): agregar carga de documentos','feat(reports): agregar reporte de usuarios','feat(permisos): implementar módulo de administración de permisos'];
  const $=id=>document.getElementById(id);
  const options=(items,current)=>items.map(([value,label])=>`<option value="${esc(value)}"${value===current?' selected':''}>${esc(label)}</option>`).join('');
  const field=(label,id,control,hint='')=>`<div class="sem-field"><label for="${id}">${label}</label>${control}${hint?`<small>${hint}</small>`:''}</div>`;
  const input=(id,group,key,value,extra='')=>`<input id="${id}" data-sem-field="${group}:${key}" value="${esc(value)}" ${extra}>`;
  const select=(id,group,key,items,current)=>`<select id="${id}" data-sem-field="${group}:${key}">${options(items,current)}</select>`;
  const copy=(key,label='Copiar')=>`<button class="sem-copy" data-sem-copy="${key}">${icon('copy')}${label}</button>`;
  const source=(url,label)=>`<a class="source-link" href="${url}" target="_blank" rel="noopener noreferrer">${label} ${icon('external')}</a>`;
  const box=(title,content)=>`<article class="sem-card"><h3>${title}</h3>${content}</article>`;
  function commitModel(){return S.commit({...values.commit,scope:values.commit.scope==='none'?'':values.commit.scope==='custom'?values.commit.customScope:values.commit.scope});}
  const branchModel=()=>S.branch(values.branch);
  const versionModel=()=>S.nextVersion(values.version.current,values.version.change);
  function commitView(){
    const v=values.commit,model=commitModel();
    return `<div class="sem-intro"><span class="eyebrow">CONVENCIÓN DE MENSAJES</span><h3>Que el historial explique el cambio.</h3><p>Formato: <code>&lt;tipo&gt;(&lt;alcance&gt;): &lt;descripción breve&gt;</code>. El alcance es opcional: <code>build: actualizar dependencias</code> también es válido.</p></div>
    ${box('Construye tu mensaje',`<div class="sem-form-grid">${field('Tipo','commit-type',select('commit-type','commit','type',S.commitTypes.map(t=>[t.type,t.type]),v.type))}${field('Alcance','commit-scope',select('commit-scope','commit','scope',[['none','Sin alcance'],...S.scopes.map(s=>[s.scope,s.scope]),['custom','Personalizado…']],v.scope))}<div id="commit-custom-wrap"${v.scope!=='custom'?' hidden':''}>${field('Alcance personalizado','commit-custom',input('commit-custom','commit','customScope',v.customScope),'Por ejemplo: permisos. Se normaliza a minúsculas y guiones.')}</div><div class="sem-wide">${field('Descripción breve','commit-description',input('commit-description','commit','description',v.description,'maxlength="240"'),'Usa un verbo como agregar, corregir o actualizar. Recomendación del equipo: minúscula inicial, sin punto final y un cambio coherente por commit.')}</div></div><label class="sem-check"><input id="commit-breaking" type="checkbox" data-sem-field="commit:breaking"${v.breaking?' checked':''}> Rompe compatibilidad del contrato público</label><div id="commit-breaking-wrap"${!v.breaking?' hidden':''}>${field('Qué cambia y cómo migrar (opcional)','commit-breaking-detail',input('commit-breaking-detail','commit','breakingDetail',v.breakingDetail,'placeholder="El endpoint requiere ahora el campo role_id"'),'Se añade ! antes de los dos puntos. Si describes el impacto, también se incluye el pie BREAKING CHANGE.')}</div><div class="sem-output-head"><span>MENSAJE</span>${copy('commit-message','Copiar mensaje')}</div><pre class="sem-output"><code id="commit-output">${esc(model.message||'')}</code></pre><div id="commit-feedback" class="sem-feedback" role="status"></div><details class="sem-command"><summary>Usarlo en la terminal</summary><div class="sem-output-head"><span>Revisa antes git diff --staged</span>${copy('commit-command','Copiar comando')}</div><pre class="sem-output"><code id="commit-command">${esc(model.command||'')}</code></pre><p>En VS Code pega solo el mensaje en Control de código fuente. Ningún botón ejecuta Git.</p></details>`)}
    <div class="sem-notice">${icon('book')}<p><strong>Convención del equipo, basada en Conventional Commits.</strong> Tu catálogo admite los 12 tipos siguientes. <code>config</code> es una extensión del equipo; si después incorporas commitlint o un generador de versiones, tendrás que configurar sus reglas. Esta página no instala hooks ni automatiza releases.</p></div>
    <details class="sem-reference" open><summary>Tipos de commit <span>12 tipos · descripción y ejemplo</span></summary><div class="sem-table"><table><thead><tr><th>Tipo</th><th>Descripción</th><th>Ejemplo copiable</th></tr></thead><tbody>${S.commitTypes.map((t,i)=>`<tr><th><code>${t.type}</code></th><td>${esc(t.description)}</td><td><div class="sem-example"><code>${esc(t.example)}</code>${copy('type:'+i)}</div></td></tr>`).join('')}</tbody></table></div></details>
    <details class="sem-reference"><summary>Alcances del sistema <span>14 alcances + módulos propios</span></summary><p>El alcance indica la parte del sistema afectada. Usa un nombre de módulo que el equipo reconozca.</p><div class="sem-table"><table><thead><tr><th>Alcance</th><th>Descripción</th></tr></thead><tbody>${S.scopes.map(s=>`<tr><th><code>${s.scope}</code></th><td>${esc(s.description)}</td></tr>`).join('')}</tbody></table></div></details>
    ${box('Ejemplos con tus alcances',`<div class="sem-samples">${examples.map((s,i)=>`<div class="sem-example"><code>${esc(s)}</code>${copy('example:'+i)}</div>`).join('')}</div><p class="sem-muted">Si una funcionalidad abarca varias capas, usa el módulo funcional, como <code>permisos</code>. Si los cambios tienen objetivos independientes, sepáralos en commits.</p>`)}
    <div class="sem-rule-grid"><div><strong>feat → MINOR</strong><p>Nueva funcionalidad compatible.</p></div><div><strong>fix → PATCH</strong><p>Corrección compatible.</p></div><div><strong>! / BREAKING CHANGE → MAJOR</strong><p>Incompatibilidad pública, en cualquier tipo.</p></div></div><p class="sem-muted">Otros tipos, incluidos perf, config y revert, no tienen un incremento SemVer implícito en Conventional Commits. Evalúa el impacto real y la política del proyecto. En versiones 0.x.y acuerda una política específica.</p><div class="sem-sources">${source('https://www.conventionalcommits.org/en/v1.0.0/','Conventional Commits 1.0.0')}</div>`;
  }
  function branchView(){
    const v=values.branch;
    return `<div class="sem-intro"><span class="eyebrow">SEMÁNTICA DE RAMAS</span><h3>El nombre dice qué trabajo contiene.</h3><p>Convención propuesta: <code>feature/&lt;alcance&gt;-&lt;ticket&gt;-&lt;descripcion&gt;</code>. Alcance y ticket son opcionales. Usa minúsculas ASCII y guiones; evita espacios, acentos y nombres vagos.</p></div>
    ${box('Construye el nombre de la rama',`<div class="sem-form-grid">${field('Objetivo','branch-kind',select('branch-kind','branch','kind',[['feature','Feature · trabajo para develop'],['release','Release · estabilizar versión'],['hotfix','Hotfix · corregir producción']],v.kind))}<div id="branch-version-wrap"${v.kind==='feature'?' hidden':''}>${field('Versión de destino','branch-version',input('branch-version','branch','version',v.version),'X.Y.Z sin prefijo v, por ejemplo 1.3.0.')}</div><div id="branch-work-wrap" class="sem-wide sem-form-grid"${v.kind!=='feature'?' hidden':''}>${field('Alcance (opcional)','branch-scope',input('branch-scope','branch','scope',v.scope))}${field('Ticket (opcional)','branch-ticket',input('branch-ticket','branch','ticket',v.ticket))}<div class="sem-wide">${field('Descripción','branch-description',input('branch-description','branch','description',v.description),'Ejemplo: recuperar contraseña → recuperar-contrasena.')}</div></div></div><div class="sem-output-head"><span>NOMBRE COMPLETO</span>${copy('branch-name','Copiar nombre')}</div><pre class="sem-output"><code id="branch-output"></code></pre><div id="branch-feedback" class="sem-feedback" role="status"></div><div class="sem-output-head"><span>TERMINAL · GIT FLOW NEXT</span>${copy('branch-command','Copiar comando')}</div><pre class="sem-output"><code id="branch-command"></code></pre><p class="sem-muted" id="branch-vscode"></p><p class="sem-muted">Git Flow Next añade el prefijo de la rama. Introduce solo el nombre corto en su comando Start. En ambos casos revisa primero el estado del repositorio y la rama base.</p>`)}
    <div class="sem-table sem-card"><table><thead><tr><th>Rama / ejemplo</th><th>Significado</th><th>Origen → destino</th></tr></thead><tbody><tr><th><code>main</code></th><td>Producción; recibe versiones aprobadas.</td><td>Releases y hotfixes</td></tr><tr><th><code>develop</code></th><td>Integra el trabajo de la próxima versión.</td><td>Features → develop</td></tr><tr><th><code>feature/auth-123-recuperar-contrasena</code></th><td>Tarea de autenticación, ticket 123.</td><td>develop → develop</td></tr><tr><th><code>release/1.3.0</code></th><td>Estabiliza la versión 1.3.0.</td><td>develop → main + develop</td></tr><tr><th><code>hotfix/1.2.4</code></th><td>Arreglo urgente para producción.</td><td>main → main + develop</td></tr></tbody></table></div>
    <div class="sem-notice">${icon('branch')}<p><strong>Tipo de rama y tipo de commit son conceptos distintos.</strong> Una feature puede incluir commits <code>feat</code>, <code>test</code>, <code>docs</code> o <code>refactor</code>. No necesitas crear <code>git flow docs start</code> ni <code>git flow config start</code>; esos tipos de rama solo existirían con una configuración adicional.</p></div><p class="sem-muted">main puede llamarse master en tu equipo. Los prefijos y el patrón alcance-ticket-descripción son acuerdos del proyecto. Un hotfix suele ser PATCH, pero la versión se decide por compatibilidad, no por el prefijo de la rama.</p><div class="sem-sources">${source('https://git-flow.sh/docs/commands/','Nombres y prefijos en Git Flow Next')}</div>`;
  }
  function versionView(){
    const v=values.version;
    return `<div class="sem-intro"><span class="eyebrow">VERSIONADO SEMÁNTICO</span><h3>MAJOR.MINOR.PATCH</h3><p>La versión comunica compatibilidad del contrato público. Una versión se decide por el conjunto de cambios que vas a publicar, no por cada commit aislado.</p></div><div class="sem-rule-grid"><div><strong>MAJOR</strong><p>Cambio incompatible.<br><code>1.2.3 → 2.0.0</code></p></div><div><strong>MINOR</strong><p>Funcionalidad compatible.<br><code>1.2.3 → 1.3.0</code></p></div><div><strong>PATCH</strong><p>Corrección compatible.<br><code>1.2.3 → 1.2.4</code></p></div></div>
    ${box('Elige la siguiente versión',`<div class="sem-form-grid">${field('Versión estable actual','semver-current',input('semver-current','version','current',v.current,'placeholder="1.2.3"'),'Sin v ni sufijos. El asistente cubre versiones estables desde 1.0.0.')}${field('Mayor impacto del conjunto','semver-change',select('semver-change','version','change',[['patch','PATCH · solo correcciones compatibles'],['minor','MINOR · nueva función compatible'],['major','MAJOR · rompe compatibilidad pública'],['none','Mantenimiento · sin incremento implícito']],v.change))}</div><div id="version-feedback" class="sem-feedback" role="status"></div><div class="sem-version-result"><span>SIGUIENTE VERSIÓN</span><strong id="version-output"></strong>${copy('version','Copiar versión')}</div><div id="version-artifacts" class="sem-artifacts"><div><span>Rama de estabilización</span><code id="version-branch"></code>${copy('version-branch')}</div><div><span>Etiqueta de Git</span><code id="version-tag"></code>${copy('version-tag')}</div><div><span>Posible candidata</span><code id="version-candidate"></code>${copy('version-candidate')}</div></div><p class="sem-muted">Si hay tres fix y un feat compatible, el conjunto sube MINOR. Si cualquiera rompe el contrato público, prevalece MAJOR. No se suma un incremento por cada commit.</p>`)}
    <div class="sem-table sem-card"><table><thead><tr><th>Elemento</th><th>Ejemplo</th><th>Interpretación</th></tr></thead><tbody><tr><th>Versión estable</th><td><code>1.3.0</code></td><td>MAJOR.MINOR.PATCH, sin ceros iniciales.</td></tr><tr><th>Rama de release</th><td><code>release/1.3.0</code></td><td>Rama mutable de estabilización; no es una etiqueta.</td></tr><tr><th>Tag estable</th><td><code>v1.3.0</code></td><td>v es una convención del nombre de etiqueta, no parte del número SemVer.</td></tr><tr><th>Prelanzamiento</th><td><code>1.3.0-rc.1</code></td><td>Candidata de menor precedencia que 1.3.0. No la presentes como versión estable.</td></tr><tr><th>Metadatos</th><td><code>1.3.0+build.7</code></td><td>Identifican una compilación y no alteran la precedencia SemVer.</td></tr></tbody></table></div><p class="sem-sequence"><code>1.3.0-alpha.1 &lt; 1.3.0-beta.1 &lt; 1.3.0-rc.1 &lt; 1.3.0</code></p>
    <div class="sem-notice">${icon('shield')}<p><strong>Una versión publicada se conserva.</strong> No reutilices su número ni muevas su etiqueta para reemplazar el contenido: publica una versión nueva. Gitflow, los mensajes de commit y este asistente no cambian por sí solos package.json, composer.json ni tus despliegues.</p></div><p class="sem-muted">En 0.x.y el contrato todavía no es estable: acuerda una política de desarrollo inicial. Para versiones estables, define qué considera tu equipo API o contrato público y revisa la migración de cualquier incompatibilidad.</p><div class="sem-sources">${source('https://semver.org/lang/es/','SemVer 2.0.0')}${source('https://www.conventionalcommits.org/en/v1.0.0/','Commits y compatibilidad')}</div>`;
  }
  function diagramPanel(){const d=S.diagrams.find(d=>d.id===values.diagram);return `<figure><div class="sem-diagram-scroll"><img src="${d.file}" alt="${esc(d.alt)}" width="940" height="400"></div><figcaption>${esc(d.caption)}</figcaption></figure><ol class="sem-diagram-steps">${d.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="sem-sources"><button class="source-link local-image-button" type="button" data-local-image="${d.id}">Ampliar imagen ${icon('external')}</button>${source('https://nvie.com/posts/a-successful-git-branching-model/','Modelo original')}${source('https://git-flow.sh/docs/commands/','Comportamiento de Next')}</div>`;}
  function mergeView(){return `<div class="sem-intro"><span class="eyebrow">UNIONES VISUALES</span><h3>De dónde sale cada rama y dónde termina.</h3><p>Elige un flujo para ver sus commits, el punto de integración y la etiqueta. Son esquemas de un cierre con merge, no una captura de tu repositorio.</p></div><div class="sem-diagram-tabs" role="group" aria-label="Elegir diagrama de unión">${S.diagrams.map(d=>`<button data-sem-diagram="${d.id}" class="${d.id===values.diagram?'active':''}" aria-pressed="${d.id===values.diagram}">${d.title}</button>`).join('')}</div><article class="sem-card sem-diagram-card" id="sem-diagram-panel">${diagramPanel()}</article><div class="sem-notice">${icon('book')}<p><strong>Lee el resultado, no solo el nombre de la acción.</strong> Los círculos representan commits; las curvas muestran creación o integración de ramas, y el tiempo avanza a la derecha. Squash o fast-forward pueden producir un grafo distinto. Con PR obligatorios, realiza la integración en el servidor y evita repetirla después con finish local.</p></div>`;}
  function render(topic,helpers){esc=helpers.esc;icon=helpers.icon;return `<div class="sem-topics" role="group" aria-label="Convenciones de Gitflow">${S.topics.map(([id,label])=>`<button data-sem-topic="${id}" class="${topic===id?'active':''}" aria-pressed="${topic===id}">${label}</button>`).join('')}</div><section class="sem-content" aria-label="${esc(S.topics.find(t=>t[0]===topic)?.[1]||'Convenciones')}">${({commits:commitView,branches:branchView,versions:versionView,merges:mergeView}[topic]||commitView)()}</section>`;}
  function setText(id,value){if($(id))$(id).textContent=value;}
  function enable(keys,enabled){for(const key of keys)document.querySelectorAll(`[data-sem-copy="${key}"]`).forEach(b=>b.disabled=!enabled);}
  function refresh(){
    if($('commit-output')){const m=commitModel();setText('commit-output',m.valid?m.message:'Completa la descripción para generar el mensaje.');setText('commit-command',m.valid?m.command:'');setText('commit-feedback',m.valid?`${m.length} caracteres en el encabezado${m.length>72?' · Recomendación: intenta resumirlo a 72 o menos':''} · Impacto orientativo: ${m.impact}`:m.error);$('commit-custom-wrap').hidden=values.commit.scope!=='custom';$('commit-breaking-wrap').hidden=!values.commit.breaking;enable(['commit-message','commit-command'],m.valid);}
    if($('branch-output')){const m=branchModel();setText('branch-output',m.valid?m.name:'Completa un nombre válido.');setText('branch-command',m.valid?m.command:'');setText('branch-vscode',m.valid?'En VS Code: '+m.vscode:'');setText('branch-feedback',m.valid?'Nombre normalizado. El prefijo de rama y el alcance no determinan el tipo de commit.':m.error);$('branch-work-wrap').hidden=values.branch.kind!=='feature';$('branch-version-wrap').hidden=values.branch.kind==='feature';enable(['branch-name','branch-command'],m.valid);}
    if($('version-output')){const m=versionModel();setText('version-output',m.valid?m.bump?m.version:'Sin incremento implícito':'Revisar versión');setText('version-feedback',m.valid?m.bump?'Se reinician a cero los componentes inferiores cuando subes MAJOR o MINOR.':m.message:m.error);$('version-artifacts').hidden=!m.valid||!m.bump;for(const [id,key] of [['version-tag','tag'],['version-branch','branch'],['version-candidate','candidate']])setText(id,m[key]||'');enable(['version','version-tag','version-branch','version-candidate'],m.valid&&m.bump);}
  }
  function update(target){const parts=target.dataset.semField?.split(':');if(!parts)return;const [group,key]=parts;if(!Object.hasOwn(values,group)||!Object.hasOwn(values[group],key))return;values[group][key]=target.type==='checkbox'?target.checked:target.value;refresh();}
  function copyText(key){
    if(key==='commit-message'||key==='commit-command'){const m=commitModel();return m.valid?(key==='commit-message'?m.message:m.command):null;}
    if(key==='branch-name'||key==='branch-command'){const m=branchModel();return m.valid?(key==='branch-name'?m.name:m.command):null;}
    if(['version','version-tag','version-branch','version-candidate'].includes(key)){const m=versionModel();return m.valid&&m.bump?m[{version:'version','version-tag':'tag','version-branch':'branch','version-candidate':'candidate'}[key]]:null;}
    const [kind,index]=key.split(':');if(kind==='type')return S.commitTypes[Number(index)]?.example||null;if(kind==='example')return examples[Number(index)]||null;return null;
  }
  function selectDiagram(id){if(!S.diagrams.some(d=>d.id===id))return;values.diagram=id;document.querySelectorAll('[data-sem-diagram]').forEach(b=>{b.classList.toggle('active',b.dataset.semDiagram===id);b.setAttribute('aria-pressed',String(b.dataset.semDiagram===id));});if($('sem-diagram-panel'))$('sem-diagram-panel').innerHTML=diagramPanel();}
  return {render,refresh,update,copyText,selectDiagram};
})();

;

/* ===== busqueda ===== */
globalThis.AtlasSearch = (() => {
  const normalize = s => String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  const stop = new Set('a al la las el los un una unos unas de del en con por para y o como que quiero necesito tras despues antes mi mis su sus dentro desde hacer tengo esta este es se lo le'.split(' '));
  const groups = [
    ['copiar','copia','copio','transferir','transferencia','enviar','envio'],
    ['reiniciar','reinicio','reinicia','reiniciar','restart','rearrancar'],
    ['cambiar','cambie','cambios','cambio','modificar','modificado','editar','actualizar','actualizado'],
    ['archivo','archivos','fichero','ficheros'],['carpeta','carpetas','directorio','directorios'],
    ['buscar','busco','encontrar','localizar','encontrar'],['ver','mostrar','listar','consultar'],
    ['eliminar','borrar','quitar','limpiar'],['descargar','bajar','traer','download'],
    ['subir','upload','cargar'],['servicio','servicios','service'],['contenedor','contenedores','container'],
    ['clave','claves','llave','llaves','key'],['log','logs','registro','registros'],
    ['conectar','conectarme','conectarse','conexion','acceder','entrar'],
    ['guardar','guardado','salvar'],['espacio','almacenamiento','disco'],
    ['deshacer','revertir','revert','anular'],['detener','parar','apagar','stop'],
    ['iniciar','empezar','crear','arrancar'],['terminar','finalizar','cerrar','finish'],
    ['feature','funcionalidad'],['release','lanzamiento'],['conflicto','conflictos'],
    ['cancelar','abortar','abort']
  ];
  const canonical = new Map();
  groups.forEach(g=>g.forEach(t=>canonical.set(t,g[0])));
  const tokens = s => [...new Set((normalize(s).match(/[a-z0-9_.-]+/g)||[]).filter(t=>!stop.has(t)).map(t=>canonical.get(t)||t))];
  function score(recipe,query) {
    if(!query.trim()) return 1;
    const q = normalize(query), qt=tokens(q);
    if(!qt.length) return 1;
    const title=tokens(recipe.title), aliases=tokens(recipe.keywords), body=tokens(recipe.desc+' '+recipe.tool+' '+recipe.steps.map(s=>s.code).join(' ')+(recipe.vscode?' vscode visual studio code editor '+recipe.vscode.map(s=>s.label+' '+s.text).join(' '):''));
    let hits=0, points=0;
    for(const t of qt) {
      const match = a=>a.some(x=>x===t || (t.length>=4 && x.startsWith(t)));
      if(match(title)){hits++;points+=8;}
      else if(match(aliases)){hits++;points+=5;}
      else if(match(body)){hits++;points+=2;}
    }
    if(hits/qt.length < .5) return 0;
    points *= hits/qt.length;
    if(normalize(recipe.title).includes(q)) points+=25;
    if(q.includes('.env') && recipe.id==='docker-env') points+=32;
    if(q.includes('.env') && recipe.id==='linux-service') points+=22;
    if(/systemd|systemctl/.test(q) && recipe.id==='linux-service') points+=35;
    if(/(copiar|enviar|subir).*archivo.*ssh/.test(q) && recipe.id==='ssh-upload') points+=35;
    if(/descargar|bajar|desde.*servidor/.test(q) && recipe.id==='ssh-download') points+=28;
    return points;
  }
  function search(recipes,query,{tool='all',goal='all',risk='all'}={}) {
    return recipes.map((recipe,index)=>({recipe,index,score:score(recipe,query)})).filter(x=>x.score>0 && (tool==='all'||x.recipe.tool===tool) && (goal==='all'||x.recipe.goal===goal) && (risk==='all'||x.recipe.risk===risk)).sort((a,b)=>b.score-a.score||a.index-b.index).map(x=>x.recipe);
  }
  return {normalize,tokens,score,search};
})();

;

